implementation:
size_t RegisterMPCImage(void) {
  MagickInfo *magick_info;

  magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(MagickInfo));
  if (magick_info == (MagickInfo *) NULL)
    return 0;

  (void) memset(magick_info, 0, sizeof(MagickInfo));
  magick_info->signature = MagickSignature; /* Assign a unique signature to the structure. */
  magick_info->name = (char *) "MPC";
  magick_info->description = (char *) "Magick Persistent Cache";
  magick_info->module = (char *) "MPC";
  magick_info->decoder = (DecodeImageHandler *) ReadMPCImage;
  magick_info->encoder = (EncodeImageHandler *) WriteMPCImage;
  magick_info->adjoin = MagickFalse;
  magick_info->raw = MagickTrue;

  return sizeof(MagickInfo);
}
